INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('80e6ad11-35cc-53f6-91c2-1834eba7df39'::uuid, '2fcdd72f-a8f8-53c7-99e7-9b753719cae9'::uuid, 'Colonne pharmacie anthracite', 'La colonne pharmacie est un accessoire de rangement haut de gamme, conçu pour optimiser l''espace vertical dans les cuisines modernes elle permet un accès facile et complet', 'Door hardware', NULL, NULL, 2150.0, 'MAD', 'Pièce', '1 Pièce', 'https://lechantier.ma/uploads/media/cf1759d1fa9a.webp', $j$["https://lechantier.ma/uploads/media/cf1759d1fa9a.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/accessoires-de-portes/colonne-pharmacie-anthracite", "category_fr": "Quincaillerie", "supplier_matching_status": "matched", "technical_specifications_detailed": "• ⚙️ Structure métallique robuste avec finition chromée, inox ou anthracite, résistante à la corrosion.🛠️ Système coulissant à sortie totale sur rails à billes ou à amortisseurs pour une ouverture fluide et silencieuse.🧺 Paniers réglables en hauteur, idéals pour ranger conserves, bouteilles, épices ou produits ménagers.🚪 Installation simple sur caisson de différentes dimensions (largeur 30, 40, 45, 60 cm, etc.).💡 Design moderne et fonctionnel, s’adaptant à tous les styles de cuisine.", "technical_specifications_original": "• ⚙️ Structure métallique robuste avec finition chromée, inox ou anthracite, résistante à la corrosion.🛠️ Système coulissant à sortie totale sur rails à billes ou à amortisseurs pour une ouverture fluide et silencieuse.🧺 Paniers réglables en hauteur, idéals pour ranger conserves, bouteilles, épices ou produits ménagers.🚪 Installation simple sur caisson de différentes dimensions (largeur 30, 40, 45, 60 cm, etc.).💡 Design moderne et fonctionnel, s’adaptant à tous les styles de cuisine.", "specs": "• ⚙️ Structure métallique robuste avec finition chromée, inox ou anthracite, résistante à la corrosion.🛠️ Système coulissant à sortie totale sur rails à billes ou à amortisseurs pour une ouverture fluide et silencieuse.🧺 Paniers réglables en hauteur, idéals pour ranger conserves, bouteilles, épices ou produits ménagers.🚪 Installation simple sur caisson de différentes dimensions (largeur 30, 40, 45, 60 cm, etc.).💡 Design moderne et fonctionnel, s’adaptant à tous les styles de cuisine."}$j$::jsonb, 'https://lechantier.ma/en/produits/accessoires-de-portes/colonne-pharmacie-anthracite') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
