INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('2b2d933f-917a-52bf-8fa6-159263ca5fee'::uuid, '2fcdd72f-a8f8-53c7-99e7-9b753719cae9'::uuid, 'Range epice Anthracite', 'Porte-Épices – Organisation et élégance dans votre cuisine Le porte-épices est un accessoire pratique et esthétique, conçu pour garder vos épices à portée de main', 'Door hardware', NULL, NULL, 650.0, 'MAD', 'Pièce', '1 Pièce', 'https://lechantier.ma/uploads/media/3b969bb8f99b.webp', $j$["https://lechantier.ma/uploads/media/3b969bb8f99b.webp", "https://lechantier.ma/uploads/media/5d4627f1860f.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/accessoires-de-portes/range-epice-anthracite", "category_fr": "Quincaillerie", "supplier_matching_status": "matched", "technical_specifications_detailed": "• 🧂 Structure en acier inoxydable ou aluminium, résistante à la corrosion et facile à nettoyer.⚙️ Fixation simple : à poser, à suspendre ou à encastrer dans un tiroir selon le modèle.🔄 Design compact et fonctionnel, permettant un accès rapide à vos condiments et épices.📏 Disponible en plusieurs dimensions et configurations, pour s’adapter à tout type de cuisine.🧴 Support stable pour flacons et bocaux, évitant les renversements.", "technical_specifications_original": "• 🧂 Structure en acier inoxydable ou aluminium, résistante à la corrosion et facile à nettoyer.⚙️ Fixation simple : à poser, à suspendre ou à encastrer dans un tiroir selon le modèle.🔄 Design compact et fonctionnel, permettant un accès rapide à vos condiments et épices.📏 Disponible en plusieurs dimensions et configurations, pour s’adapter à tout type de cuisine.🧴 Support stable pour flacons et bocaux, évitant les renversements.", "specs": "• 🧂 Structure en acier inoxydable ou aluminium, résistante à la corrosion et facile à nettoyer.⚙️ Fixation simple : à poser, à suspendre ou à encastrer dans un tiroir selon le modèle.🔄 Design compact et fonctionnel, permettant un accès rapide à vos condiments et épices.📏 Disponible en plusieurs dimensions et configurations, pour s’adapter à tout type de cuisine.🧴 Support stable pour flacons et bocaux, évitant les renversements."}$j$::jsonb, 'https://lechantier.ma/en/produits/accessoires-de-portes/range-epice-anthracite') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
