INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('2fe6ef2b-1e90-5877-b42f-9b1db215ad5d'::uuid, '8aeabc95-fac4-59f0-be4c-7bcca0cf6034'::uuid, 'Treillis soudé 3,5*3,5', 'Treillis soudé en acier nervuré, idéal pour l''armature des dalles, planchers et radiers. Offre une excellente résistance à la traction et à la fissuration.', 'Steel', NULL, NULL, 95.0, 'MAD', 'm²', '5 Mètre', 'https://lechantier.ma/uploads/media/2cf33ccee9d2.webp', $j$["https://lechantier.ma/uploads/media/2cf33ccee9d2.webp"]$j$::jsonb, $j$["Meknès"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/acier/treillis-soude-3-5-3-5", "category_fr": "Steel", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Produit : Treillis soudéType : Treillis en acier nervuré haute adhérenceFormat standard : 2,4 m x 6 m (autres dimensions sur commande)Diamètre des fils : de 4 mm à 8 mm (selon référence)Maille courante : 300 x 200 mmMatière : Acier HA (Haute adhérence) type B500A ou B500B Utilisation :· Renforcement des dalles, planchers, radier, voiles, fondations, etc.· Utilisé en construction neuve ou en rénovationAvantages :· Pose rapide grâce aux grands formats· Contrôle qualité en usine, espacement régulier· Améliore la répartition des efforts et limite la fissuration· Compatible avec tous types de béton", "technical_specifications_original": "• Produit : Treillis soudéType : Treillis en acier nervuré haute adhérenceFormat standard : 2,4 m x 6 m (autres dimensions sur commande)Diamètre des fils : de 4 mm à 8 mm (selon référence)Maille courante : 300 x 200 mmMatière : Acier HA (Haute adhérence) type B500A ou B500B Utilisation :· Renforcement des dalles, planchers, radier, voiles, fondations, etc.· Utilisé en construction neuve ou en rénovationAvantages :· Pose rapide grâce aux grands formats· Contrôle qualité en usine, espacement régulier· Améliore la répartition des efforts et limite la fissuration· Compatible avec tous types de béton", "specs": "• Produit : Treillis soudéType : Treillis en acier nervuré haute adhérenceFormat standard : 2,4 m x 6 m (autres dimensions sur commande)Diamètre des fils : de 4 mm à 8 mm (selon référence)Maille courante : 300 x 200 mmMatière : Acier HA (Haute adhérence) type B500A ou B500B Utilisation :· Renforcement des dalles, planchers, radier, voiles, fondations, etc.· Utilisé en construction neuve ou en rénovationAvantages :· Pose rapide grâce aux grands formats· Contrôle qualité en usine, espacement régulier· Améliore la répartition des efforts et limite la fissuration· Compatible avec tous types de béton"}$j$::jsonb, 'https://lechantier.ma/en/produits/acier/treillis-soude-3-5-3-5') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
