INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('a3422706-3f08-592b-ba36-566f64b95eea'::uuid, 'af7b7862-65b0-5f91-a6a7-b82461df0216'::uuid, 'Moustiquaire plissée', 'La moustiquaire plissée est une solution moderne, discrète et sur-mesure conçue pour protéger les intérieurs contre les insectes tout en préservant la circulation de l''air et la lumière naturelle. Elle est particulièrement adaptée aux fenêtres, portes-fenêtres et grandes baies coulissantes. Fonctionnement et Ergonomie * Ouverture en accordéon : La toile se replie proprement sur elle-même latéralement ou verticalement, réduisant l''encombrement au minimum lorsque la moustiquaire est ouverte. * A', 'Aluminium', 'Volet roulant', NULL, 550.0, 'MAD', 'm²', '500 m²', 'https://lechantier.ma/uploads/media/f254f8dc682b.webp', $j$["https://lechantier.ma/uploads/media/f254f8dc682b.webp", "https://lechantier.ma/uploads/media/6db676808180.webp", "https://lechantier.ma/uploads/media/4049081b35cb.webp", "https://lechantier.ma/uploads/media/a7c1ff2a5fd4.webp", "https://lechantier.ma/uploads/media/652315d2d7ff.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/aluminium/moustiquaire-plissee", "category_fr": "Aluminium", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Moustiquaire plissée هوا عبارة عن إطار الومنيوم مجهز بنضام إنزلاق و تركب به شبكة من pvc غير قالبلة للإشتعال و متينة تحمي من الحشرات و الزواحف", "technical_specifications_original": "• Moustiquaire plissée هوا عبارة عن إطار الومنيوم مجهز بنضام إنزلاق و تركب به شبكة من pvc غير قالبلة للإشتعال و متينة تحمي من الحشرات و الزواحف", "specs": "• Moustiquaire plissée هوا عبارة عن إطار الومنيوم مجهز بنضام إنزلاق و تركب به شبكة من pvc غير قالبلة للإشتعال و متينة تحمي من الحشرات و الزواحف"}$j$::jsonb, 'https://lechantier.ma/en/produits/aluminium/moustiquaire-plissee') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('722f90ad-1b69-5b3c-aa19-8cc158ac337b'::uuid, 'ae30cf07-12e8-5460-aaea-39c2841f9d16'::uuid, 'Béton decoratif', 'L''esthétique au service de la performance chez my zdayn le béton ne se limite pas à la structure. il devient une matière de design, un outils d''expression architecturale', 'Other', NULL, NULL, 220.0, 'MAD', 'm²', '500 Mètre', 'https://lechantier.ma/uploads/media/540fbd440f25.webp', $j$["https://lechantier.ma/uploads/media/540fbd440f25.webp", "https://lechantier.ma/uploads/media/9ade175f632a.webp", "https://lechantier.ma/uploads/media/e0b5af76a512.webp", "https://lechantier.ma/uploads/media/6e0f0c98276e.webp", "https://lechantier.ma/uploads/media/f3252af4ef34.webp", "https://lechantier.ma/uploads/media/e3d5e61dd3ae.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/amenagement-exterieur-autres/beton-decoratif", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Le béton décoratif est une solution à la fois solide, durable et élégante, utilisée pour valoriser les sols et surfaces intérieures ou extérieures. Adapté aux environnements résidentiels, commerciaux ou publics, il offre une finiton haut de gamme avec de multiples rendus possibles.Nos types de béton décoratifBéton lissé ou quartzé : pour un effet moderne, industriel et brillantBéton imprimé : reproduit l’aspect de la pierre, du bois ou du pavéBéton désactivé : aspect gravillonné antidérapant, parfait pour l’extérieurBéton ciré : idéal pour les sols intérieurs design et épurésBéton poncé et poli : révèle les agrégats, effet terrazzo ou marbreBéton coloré dans la masse : personnalisation de teinte garantieAvantages du béton décoratifEsthétique moderne et personnalisableGrande résistance aux chocs, à l’usure et aux intempériesEntretien facile et longue durée de vieSolution économique à long termeApplication rapide avec finitions soignéesApplicationsAllées, trottoirs, entrées de villaTerrasses, jardins, patiosMagasins, showrooms, restaurantsEspaces publics et collectifsIntérieurs contemporains (salons, bureaux…)", "technical_specifications_original": "• Le béton décoratif est une solution à la fois solide, durable et élégante, utilisée pour valoriser les sols et surfaces intérieures ou extérieures. Adapté aux environnements résidentiels, commerciaux ou publics, il offre une finiton haut de gamme avec de multiples rendus possibles.Nos types de béton décoratifBéton lissé ou quartzé : pour un effet moderne, industriel et brillantBéton imprimé : reproduit l’aspect de la pierre, du bois ou du pavéBéton désactivé : aspect gravillonné antidérapant, parfait pour l’extérieurBéton ciré : idéal pour les sols intérieurs design et épurésBéton poncé et poli : révèle les agrégats, effet terrazzo ou marbreBéton coloré dans la masse : personnalisation de teinte garantieAvantages du béton décoratifEsthétique moderne et personnalisableGrande résistance aux chocs, à l’usure et aux intempériesEntretien facile et longue durée de vieSolution économique à long termeApplication rapide avec finitions soignéesApplicationsAllées, trottoirs, entrées de villaTerrasses, jardins, patiosMagasins, showrooms, restaurantsEspaces publics et collectifsIntérieurs contemporains (salons, bureaux…)", "specs": "• Le béton décoratif est une solution à la fois solide, durable et élégante, utilisée pour valoriser les sols et surfaces intérieures ou extérieures. Adapté aux environnements résidentiels, commerciaux ou publics, il offre une finiton haut de gamme avec de multiples rendus possibles.Nos types de béton décoratifBéton lissé ou quartzé : pour un effet moderne, industriel et brillantBéton imprimé : reproduit l’aspect de la pierre, du bois ou du pavéBéton désactivé : aspect gravillonné antidérapant, parfait pour l’extérieurBéton ciré : idéal pour les sols intérieurs design et épurésBéton poncé et poli : révèle les agrégats, effet terrazzo ou marbreBéton coloré dans la masse : personnalisation de teinte garantieAvantages du béton décoratifEsthétique moderne et personnalisableGrande résistance aux chocs, à l’usure et aux intempériesEntretien facile et longue durée de vieSolution économique à long termeApplication rapide avec finitions soignéesApplicationsAllées, trottoirs, entrées de villaTerrasses, jardins, patiosMagasins, showrooms, restaurantsEspaces publics et collectifsIntérieurs contemporains (salons, bureaux…)"}$j$::jsonb, 'https://lechantier.ma/en/produits/amenagement-exterieur-autres/beton-decoratif') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
