INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('8926ea93-16a9-5045-bae5-11277ea4e7fe'::uuid, 'afef5b63-e64a-5ef7-b06f-5dc91bbd20fb'::uuid, 'Porte Rapide ZipGO', 'Porte Rapide ZipGO conçue pour compartimenter des espaces à des fins différentes. Elle offre une grande flexibilité d''utilisation grâce à sa caractéristique d''autoréparation.', 'Other', NULL, NULL, 30800.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/cf95a666a8f9.webp', $j$["https://lechantier.ma/uploads/media/cf95a666a8f9.webp", "https://lechantier.ma/uploads/media/a72569031869.webp", "https://lechantier.ma/uploads/media/c10d521b7b5d.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/amenagement-exterieur-autres/porte-rapide-zipgo", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Structure châssis :Standard galvaniséOptions : peint RAL ou inox AISI 304/316Dimensions de passage :Standard : 5000 × 5000 mmAutres dimensions sur demandeVitesse d’ouverture : jusqu’à 2,2 m/s, réglable avec accélération/décélérationVitesse de fermeture : 0,8 m/s, réglable égalementRésistance au vent :Classe 2 (selon norme UNI EN 12424)Alimentation :230 V AC monophaséBâche :Polyester ultra-résistant 950 g/m², anti-feu (Classe 2)Sans renforts rigides, coulisse dans les charnières latéralesRangée de hublots transparents à hauteur de sécurité (plus sur demande)Option : bâche isolante (réduction bruit et humidité)Motorisation :Moteur Inverter 1 kW, fins de course digitales précâbléesBoîtier de commande :Écran multilingue avec programmation intuitiveGestion précise des temps d’ouverture et fermetureDétection piétons + clignotants LED intégrésSécurité :Photocellules, barre palpeuse anti-écrasementBarrière immatérielle infrarouge intégrée (conforme UNI EN 12453)Certifications :Conforme à la norme UNI EN 13241-1Ouverture d’urgence :En option : batterie tampon pour ouverture en cas de coupure de courant", "technical_specifications_original": "• Structure châssis :Standard galvaniséOptions : peint RAL ou inox AISI 304/316Dimensions de passage :Standard : 5000 × 5000 mmAutres dimensions sur demandeVitesse d’ouverture : jusqu’à 2,2 m/s, réglable avec accélération/décélérationVitesse de fermeture : 0,8 m/s, réglable égalementRésistance au vent :Classe 2 (selon norme UNI EN 12424)Alimentation :230 V AC monophaséBâche :Polyester ultra-résistant 950 g/m², anti-feu (Classe 2)Sans renforts rigides, coulisse dans les charnières latéralesRangée de hublots transparents à hauteur de sécurité (plus sur demande)Option : bâche isolante (réduction bruit et humidité)Motorisation :Moteur Inverter 1 kW, fins de course digitales précâbléesBoîtier de commande :Écran multilingue avec programmation intuitiveGestion précise des temps d’ouverture et fermetureDétection piétons + clignotants LED intégrésSécurité :Photocellules, barre palpeuse anti-écrasementBarrière immatérielle infrarouge intégrée (conforme UNI EN 12453)Certifications :Conforme à la norme UNI EN 13241-1Ouverture d’urgence :En option : batterie tampon pour ouverture en cas de coupure de courant", "specs": "• Structure châssis :Standard galvaniséOptions : peint RAL ou inox AISI 304/316Dimensions de passage :Standard : 5000 × 5000 mmAutres dimensions sur demandeVitesse d’ouverture : jusqu’à 2,2 m/s, réglable avec accélération/décélérationVitesse de fermeture : 0,8 m/s, réglable égalementRésistance au vent :Classe 2 (selon norme UNI EN 12424)Alimentation :230 V AC monophaséBâche :Polyester ultra-résistant 950 g/m², anti-feu (Classe 2)Sans renforts rigides, coulisse dans les charnières latéralesRangée de hublots transparents à hauteur de sécurité (plus sur demande)Option : bâche isolante (réduction bruit et humidité)Motorisation :Moteur Inverter 1 kW, fins de course digitales précâbléesBoîtier de commande :Écran multilingue avec programmation intuitiveGestion précise des temps d’ouverture et fermetureDétection piétons + clignotants LED intégrésSécurité :Photocellules, barre palpeuse anti-écrasementBarrière immatérielle infrarouge intégrée (conforme UNI EN 12453)Certifications :Conforme à la norme UNI EN 13241-1Ouverture d’urgence :En option : batterie tampon pour ouverture en cas de coupure de courant"}$j$::jsonb, 'https://lechantier.ma/en/produits/amenagement-exterieur-autres/porte-rapide-zipgo') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('5ff60c0d-a721-5660-a896-029502e808ab'::uuid, 'afef5b63-e64a-5ef7-b06f-5dc91bbd20fb'::uuid, 'Portes Sectionnelles Industrielles', 'Les portes sectionnelles industrielles sont des solutions de fermeture robustes et polyvalentes, idéales pour les environnements industrielles, commerciaux et logistiques', 'Other', NULL, NULL, 5800.0, 'MAD', 'm²', '1 Mètre', 'https://lechantier.ma/uploads/media/ebdc69fd87a6.webp', $j$["https://lechantier.ma/uploads/media/ebdc69fd87a6.webp", "https://lechantier.ma/uploads/media/f1713bae4fe5.webp", "https://lechantier.ma/uploads/media/ff013f6a50c8.webp", "https://lechantier.ma/uploads/media/192ea1a76b8d.webp", "https://lechantier.ma/uploads/media/480920ac7cb8.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/amenagement-exterieur-autres/portes-sectionnelles-industrielles", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Types de levée :Levée verticale : ouverture complète vers le haut, idéale lorsque la hauteur sous plafond est suffisante.Levée semi-verticale (ou levée oblique) : combinaison entre levée verticale et horizontale, s’adapte aux bâtiments avec une hauteur de plafond moyenne.Levée normale (ou levée haute) : ouverture suivant la pente du toit ou une course horizontale, la plus courante dans les zones industrielles.Structure : Panneaux articulés en acier ou aluminium, s’ouvrant verticalement, guidés par des rails.Isolation thermique : Panneaux sandwich en tôle d’acier injectés de mousse polyuréthane (épaisseur standard : 40 à 80 mm), assurant une bonne isolation thermique et phonique.Motorisation : Fonctionnement manuel ou motorisé (commande par bouton, télécommande, badge, etc.)Étanchéité et sécurité :Joints périphériques anti-poussière et anti-pluieSécurité anti-chute (ressorts ou câbles)Détection d’obstacles en cas de motorisationPersonnalisation :Choix des couleurs RAL, finition lisse ou nervuréePossibilité d’intégrer des hublots ou un portillon de service", "technical_specifications_original": "• Types de levée :Levée verticale : ouverture complète vers le haut, idéale lorsque la hauteur sous plafond est suffisante.Levée semi-verticale (ou levée oblique) : combinaison entre levée verticale et horizontale, s’adapte aux bâtiments avec une hauteur de plafond moyenne.Levée normale (ou levée haute) : ouverture suivant la pente du toit ou une course horizontale, la plus courante dans les zones industrielles.Structure : Panneaux articulés en acier ou aluminium, s’ouvrant verticalement, guidés par des rails.Isolation thermique : Panneaux sandwich en tôle d’acier injectés de mousse polyuréthane (épaisseur standard : 40 à 80 mm), assurant une bonne isolation thermique et phonique.Motorisation : Fonctionnement manuel ou motorisé (commande par bouton, télécommande, badge, etc.)Étanchéité et sécurité :Joints périphériques anti-poussière et anti-pluieSécurité anti-chute (ressorts ou câbles)Détection d’obstacles en cas de motorisationPersonnalisation :Choix des couleurs RAL, finition lisse ou nervuréePossibilité d’intégrer des hublots ou un portillon de service", "specs": "• Types de levée :Levée verticale : ouverture complète vers le haut, idéale lorsque la hauteur sous plafond est suffisante.Levée semi-verticale (ou levée oblique) : combinaison entre levée verticale et horizontale, s’adapte aux bâtiments avec une hauteur de plafond moyenne.Levée normale (ou levée haute) : ouverture suivant la pente du toit ou une course horizontale, la plus courante dans les zones industrielles.Structure : Panneaux articulés en acier ou aluminium, s’ouvrant verticalement, guidés par des rails.Isolation thermique : Panneaux sandwich en tôle d’acier injectés de mousse polyuréthane (épaisseur standard : 40 à 80 mm), assurant une bonne isolation thermique et phonique.Motorisation : Fonctionnement manuel ou motorisé (commande par bouton, télécommande, badge, etc.)Étanchéité et sécurité :Joints périphériques anti-poussière et anti-pluieSécurité anti-chute (ressorts ou câbles)Détection d’obstacles en cas de motorisationPersonnalisation :Choix des couleurs RAL, finition lisse ou nervuréePossibilité d’intégrer des hublots ou un portillon de service"}$j$::jsonb, 'https://lechantier.ma/en/produits/amenagement-exterieur-autres/portes-sectionnelles-industrielles') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
