INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('30290aaa-b366-5c7f-966b-2984067595c7'::uuid, 'b22bf46f-53d6-5271-a13a-8606403cc486'::uuid, 'Porte en noyer naturel', 'Porte en placage noyer naturel 100%', 'Interior fit-out', NULL, NULL, 3000.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/de61621235dd.webp', $j$["https://lechantier.ma/uploads/media/de61621235dd.webp"]$j$::jsonb, $j$["Fès"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/amenagement-interieur/porte-en-noyer-naturel", "category_fr": "Interior fit-out", "supplier_matching_status": "matched", "technical_specifications_detailed": "• La porte est réalisée avec un parement en placage noyer naturel, offrant une finition élégante et chaleureuse qui met en valeur le veinage authentique du bois. Ce placage, appliqué sur un support en MDF ou en contreplaqué de haute qualité, assure une bonne stabilité dimensionnelle tout en conservant l’aspect raffiné du bois massif. Le cadre et le chambranle peuvent être assortis en bois massif ou plaqué pour une harmonie visuelle parfaite. Cette porte convient parfaitement aux espaces intérieurs haut de gamme, apportant une touche de sophistication naturelle tout en bénéficiant d’une excellente durabilité.", "technical_specifications_original": "• La porte est réalisée avec un parement en placage noyer naturel, offrant une finition élégante et chaleureuse qui met en valeur le veinage authentique du bois. Ce placage, appliqué sur un support en MDF ou en contreplaqué de haute qualité, assure une bonne stabilité dimensionnelle tout en conservant l’aspect raffiné du bois massif. Le cadre et le chambranle peuvent être assortis en bois massif ou plaqué pour une harmonie visuelle parfaite. Cette porte convient parfaitement aux espaces intérieurs haut de gamme, apportant une touche de sophistication naturelle tout en bénéficiant d’une excellente durabilité.", "specs": "• La porte est réalisée avec un parement en placage noyer naturel, offrant une finition élégante et chaleureuse qui met en valeur le veinage authentique du bois. Ce placage, appliqué sur un support en MDF ou en contreplaqué de haute qualité, assure une bonne stabilité dimensionnelle tout en conservant l’aspect raffiné du bois massif. Le cadre et le chambranle peuvent être assortis en bois massif ou plaqué pour une harmonie visuelle parfaite. Cette porte convient parfaitement aux espaces intérieurs haut de gamme, apportant une touche de sophistication naturelle tout en bénéficiant d’une excellente durabilité."}$j$::jsonb, 'https://lechantier.ma/en/produits/amenagement-interieur/porte-en-noyer-naturel') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('4e7e18cb-3d10-573a-9590-098b234deda8'::uuid, 'b22bf46f-53d6-5271-a13a-8606403cc486'::uuid, 'Porte intérieur et placard en cpl', 'Porte isoplane fabriqué a notre usine au Maroc , disponible on plusieurs couleur , bien sûr on peut faire même des placard de la meme matière', 'Interior fit-out', NULL, NULL, 1600.0, 'MAD', 'm²', '50 Pièce', 'https://lechantier.ma/uploads/media/5db1602a1543.webp', $j$["https://lechantier.ma/uploads/media/5db1602a1543.webp", "https://lechantier.ma/uploads/media/ca4e31afeac2.webp"]$j$::jsonb, $j$["Fès"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/amenagement-interieur/porte-interieur-et-placard-en-cpl", "category_fr": "Interior fit-out", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Porte interieur / extérieurLa porte cpl isoplane est constituée d’un vantail à âme pleine ou alvéolaire, revêtu de parements en MDF pour offrir une surface lisse et résistante. Elle est habillée d’un film en PVC qui lui confère une excellente résistance à l’humidité, facilitant ainsi son entretien et la rendant idéale pour des environnements tels que les salles de bains, cuisines ou locaux techniques. Le cadre, le chambranle et le cadrage sont réalisés en bois rouge massif, reconnu pour sa robustesse et sa durabilité, assurant une bonne tenue de l’ensemble dans le temps. Cette configuration allie à la fois solidité, esthétisme et fonctionnalité, tout en répondant aux exigences d’un usage intérieur dans des conditions potentiellement humides.", "technical_specifications_original": "• Porte interieur / extérieurLa porte cpl isoplane est constituée d’un vantail à âme pleine ou alvéolaire, revêtu de parements en MDF pour offrir une surface lisse et résistante. Elle est habillée d’un film en PVC qui lui confère une excellente résistance à l’humidité, facilitant ainsi son entretien et la rendant idéale pour des environnements tels que les salles de bains, cuisines ou locaux techniques. Le cadre, le chambranle et le cadrage sont réalisés en bois rouge massif, reconnu pour sa robustesse et sa durabilité, assurant une bonne tenue de l’ensemble dans le temps. Cette configuration allie à la fois solidité, esthétisme et fonctionnalité, tout en répondant aux exigences d’un usage intérieur dans des conditions potentiellement humides.", "specs": "• Porte interieur / extérieurLa porte cpl isoplane est constituée d’un vantail à âme pleine ou alvéolaire, revêtu de parements en MDF pour offrir une surface lisse et résistante. Elle est habillée d’un film en PVC qui lui confère une excellente résistance à l’humidité, facilitant ainsi son entretien et la rendant idéale pour des environnements tels que les salles de bains, cuisines ou locaux techniques. Le cadre, le chambranle et le cadrage sont réalisés en bois rouge massif, reconnu pour sa robustesse et sa durabilité, assurant une bonne tenue de l’ensemble dans le temps. Cette configuration allie à la fois solidité, esthétisme et fonctionnalité, tout en répondant aux exigences d’un usage intérieur dans des conditions potentiellement humides."}$j$::jsonb, 'https://lechantier.ma/en/produits/amenagement-interieur/porte-interieur-et-placard-en-cpl') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
