INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('72789627-aff1-5eec-a780-157f86518175'::uuid, '8137d195-6e94-5cbe-81bd-e1a8798098a6'::uuid, 'Démarreur Progressif PSTX105-600-70 -ABB', 'Démarreur progressif ABB PSTX105-600-70, contrôle précis moteurs triphasés jusqu''à 90 kW, protection intégrée, démarrage en douceur et fiabilité industrielle✅️', 'Other', NULL, NULL, 19600.0, 'MAD', 'Pièce', '1 Pièce', 'https://lechantier.ma/uploads/media/7011ed09990f.webp', $j$["https://lechantier.ma/uploads/media/7011ed09990f.webp"]$j$::jsonb, $j$["Témara"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/automatisme-autres/demarreur-progressif-pstx105-600-70-abb", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Le Démarreur Progressif ABB PSTX105-600-70 offre un démarrage et un arrêt progressifs des moteurs triphasés, tout en réduisant les contraintes mécaniques et électriques et en protégeant vos installations. Fiable. Robuste. Optimisé pour les applications industrielles et automatisées exigeantes\n• ️🔹 Technologie : Softstarter à contrôle de couple, démarrage/arrêt progressif via rampe de tension ou de couple.🔹 Courant nominal : jusqu’à 105 A.🔹 Tension d’alimentation : 208–600 V AC.🔹 Tension de commande : 100–250 V AC / 50–60 Hz.🔹 Puissance moteur :Connexion ligne : 30 kW (230 V), 55 kW (400 V), 75 kW (500 V)Connexion delta : 55 kW (230 V), 90 kW (400 V), 110 kW (500 V)🔹 Fonctions intégrées :Limitation de courant, kickstart, analog output, EOL, chauffage moteur, nettoyage de pompeJog, freinage, stand-still brake, diagnostics, séquence de démarrage, mode urgence/pompe incendieProtection intégrée : surcharge électronique, défaut à la terre, déséquilibre courant, sous-tension, inversion de phase, verrouillage rotor, protection thyristor, etc.🔹 Communication et contrôle :Modbus RTU intégré, compatible Modbus TCP, Profinet, Profibus, Ethernet/IP, EtherCAT, DeviceNet, CANopen, BACnetEntrées numériques programmables et relais de signal pour marche, dérivation, défaut, surcharge🔹 Affichage : écran graphique détachable IP66 avec visualisation claire des alarmes et signaux.🔹 Montage : vertical, +/- 10°, facile à intégrer dans coffrets et armoires industrielles.🔹 Applications : pompes, ventilateurs, compresseurs, convoyeurs et machines industrielles.🔹 Dimensions / Poids : 150 × 314 × 198 mm / 4,7 kg.🔹 Avantages clients :Démarrage et arrêt en douceur, réduisant l’usure mécaniqueProtection complète du moteur et des équipementsOptimisation énergétique et limitation des pertesIntégration facile dans systèmes d’automatisation complexes", "technical_specifications_original": "• Le Démarreur Progressif ABB PSTX105-600-70 offre un démarrage et un arrêt progressifs des moteurs triphasés, tout en réduisant les contraintes mécaniques et électriques et en protégeant vos installations. Fiable. Robuste. Optimisé pour les applications industrielles et automatisées exigeantes\n• ️🔹 Technologie : Softstarter à contrôle de couple, démarrage/arrêt progressif via rampe de tension ou de couple.🔹 Courant nominal : jusqu’à 105 A.🔹 Tension d’alimentation : 208–600 V AC.🔹 Tension de commande : 100–250 V AC / 50–60 Hz.🔹 Puissance moteur :Connexion ligne : 30 kW (230 V), 55 kW (400 V), 75 kW (500 V)Connexion delta : 55 kW (230 V), 90 kW (400 V), 110 kW (500 V)🔹 Fonctions intégrées :Limitation de courant, kickstart, analog output, EOL, chauffage moteur, nettoyage de pompeJog, freinage, stand-still brake, diagnostics, séquence de démarrage, mode urgence/pompe incendieProtection intégrée : surcharge électronique, défaut à la terre, déséquilibre courant, sous-tension, inversion de phase, verrouillage rotor, protection thyristor, etc.🔹 Communication et contrôle :Modbus RTU intégré, compatible Modbus TCP, Profinet, Profibus, Ethernet/IP, EtherCAT, DeviceNet, CANopen, BACnetEntrées numériques programmables et relais de signal pour marche, dérivation, défaut, surcharge🔹 Affichage : écran graphique détachable IP66 avec visualisation claire des alarmes et signaux.🔹 Montage : vertical, +/- 10°, facile à intégrer dans coffrets et armoires industrielles.🔹 Applications : pompes, ventilateurs, compresseurs, convoyeurs et machines industrielles.🔹 Dimensions / Poids : 150 × 314 × 198 mm / 4,7 kg.🔹 Avantages clients :Démarrage et arrêt en douceur, réduisant l’usure mécaniqueProtection complète du moteur et des équipementsOptimisation énergétique et limitation des pertesIntégration facile dans systèmes d’automatisation complexes", "specs": "• Le Démarreur Progressif ABB PSTX105-600-70 offre un démarrage et un arrêt progressifs des moteurs triphasés, tout en réduisant les contraintes mécaniques et électriques et en protégeant vos installations. Fiable. Robuste. Optimisé pour les applications industrielles et automatisées exigeantes\n• ️🔹 Technologie : Softstarter à contrôle de couple, démarrage/arrêt progressif via rampe de tension ou de couple.🔹 Courant nominal : jusqu’à 105 A.🔹 Tension d’alimentation : 208–600 V AC.🔹 Tension de commande : 100–250 V AC / 50–60 Hz.🔹 Puissance moteur :Connexion ligne : 30 kW (230 V), 55 kW (400 V), 75 kW (500 V)Connexion delta : 55 kW (230 V), 90 kW (400 V), 110 kW (500 V)🔹 Fonctions intégrées :Limitation de courant, kickstart, analog output, EOL, chauffage moteur, nettoyage de pompeJog, freinage, stand-still brake, diagnostics, séquence de démarrage, mode urgence/pompe incendieProtection intégrée : surcharge électronique, défaut à la terre, déséquilibre courant, sous-tension, inversion de phase, verrouillage rotor, protection thyristor, etc.🔹 Communication et contrôle :Modbus RTU intégré, compatible Modbus TCP, Profinet, Profibus, Ethernet/IP, EtherCAT, DeviceNet, CANopen, BACnetEntrées numériques programmables et relais de signal pour marche, dérivation, défaut, surcharge🔹 Affichage : écran graphique détachable IP66 avec visualisation claire des alarmes et signaux.🔹 Montage : vertical, +/- 10°, facile à intégrer dans coffrets et armoires industrielles.🔹 Applications : pompes, ventilateurs, compresseurs, convoyeurs et machines industrielles.🔹 Dimensions / Poids : 150 × 314 × 198 mm / 4,7 kg.🔹 Avantages clients :Démarrage et arrêt en douceur, réduisant l’usure mécaniqueProtection complète du moteur et des équipementsOptimisation énergétique et limitation des pertesIntégration facile dans systèmes d’automatisation complexes"}$j$::jsonb, 'https://lechantier.ma/en/produits/automatisme-autres/demarreur-progressif-pstx105-600-70-abb') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('628baa6f-8d38-56cc-b394-38112b24029a'::uuid, '8137d195-6e94-5cbe-81bd-e1a8798098a6'::uuid, 'Conductimètre SUP-TDS210-B', 'Le SUP-TDS210-B est un conductimètre précis pour mesurer la conductivité, le TDS et la température des liquides, idéal pour l''industrie et les laboratoires', 'Automation & smart home', NULL, NULL, 9000.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/d4352a192a50.webp', $j$["https://lechantier.ma/uploads/media/d4352a192a50.webp", "https://lechantier.ma/uploads/media/92aaa6393bd9.webp", "https://lechantier.ma/uploads/media/d4f141dc731e.webp"]$j$::jsonb, $j$["Témara"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/automatisme-domotique/conductimetre-sup-tds210-b", "category_fr": "Automation & smart home", "supplier_matching_status": "matched", "technical_specifications_detailed": "• 🔹 Le SUP-TDS210-B est un conductimètre et compteur TDS/EC précis pour mesurer la conductivité, les solides dissous (TDS) et la température des liquides.🔹 Plage de mesure selon électrode :\n• 0,01 électrode : 0 – 20,00 µS/cm\n• 0,1 électrode : 0,2 – 200,0 µS/cm\n• 1,0 électrode : 2 – 2000 µS/cm\n• 10,0 électrode : 0,02 – 20 mS/cm🔹 Précision : ±2 %, Erreur base unité électronique ±1 %FS, Température ±0,3 °C🔹 Compensation de température : NTC10K/PT1000, manuelle ou automatique, plage -10 ~ 130 °C🔹 Sorties et communication : 4–20 mA, relais 250 V/3A, RS485, Modbus-RTU🔹 Conditions de fonctionnement : 0 ~ 60 °C, humidité 10 ~ 85 % HR, alimentation AC220 V ±10 % 50/60 Hz ou DC24 V ±20 %🔹 Design compact et robuste, facile à installer, compatible avec systèmes automatisés pour un contrôle en temps réel.🔹 Idéal pour laboratoires, industries et traitement de l’eau, garantissant fiabilité, performance et maintenance minimale.", "technical_specifications_original": "• 🔹 Le SUP-TDS210-B est un conductimètre et compteur TDS/EC précis pour mesurer la conductivité, les solides dissous (TDS) et la température des liquides.🔹 Plage de mesure selon électrode :\n• 0,01 électrode : 0 – 20,00 µS/cm\n• 0,1 électrode : 0,2 – 200,0 µS/cm\n• 1,0 électrode : 2 – 2000 µS/cm\n• 10,0 électrode : 0,02 – 20 mS/cm🔹 Précision : ±2 %, Erreur base unité électronique ±1 %FS, Température ±0,3 °C🔹 Compensation de température : NTC10K/PT1000, manuelle ou automatique, plage -10 ~ 130 °C🔹 Sorties et communication : 4–20 mA, relais 250 V/3A, RS485, Modbus-RTU🔹 Conditions de fonctionnement : 0 ~ 60 °C, humidité 10 ~ 85 % HR, alimentation AC220 V ±10 % 50/60 Hz ou DC24 V ±20 %🔹 Design compact et robuste, facile à installer, compatible avec systèmes automatisés pour un contrôle en temps réel.🔹 Idéal pour laboratoires, industries et traitement de l’eau, garantissant fiabilité, performance et maintenance minimale.", "specs": "• 🔹 Le SUP-TDS210-B est un conductimètre et compteur TDS/EC précis pour mesurer la conductivité, les solides dissous (TDS) et la température des liquides.🔹 Plage de mesure selon électrode :\n• 0,01 électrode : 0 – 20,00 µS/cm\n• 0,1 électrode : 0,2 – 200,0 µS/cm\n• 1,0 électrode : 2 – 2000 µS/cm\n• 10,0 électrode : 0,02 – 20 mS/cm🔹 Précision : ±2 %, Erreur base unité électronique ±1 %FS, Température ±0,3 °C🔹 Compensation de température : NTC10K/PT1000, manuelle ou automatique, plage -10 ~ 130 °C🔹 Sorties et communication : 4–20 mA, relais 250 V/3A, RS485, Modbus-RTU🔹 Conditions de fonctionnement : 0 ~ 60 °C, humidité 10 ~ 85 % HR, alimentation AC220 V ±10 % 50/60 Hz ou DC24 V ±20 %🔹 Design compact et robuste, facile à installer, compatible avec systèmes automatisés pour un contrôle en temps réel.🔹 Idéal pour laboratoires, industries et traitement de l’eau, garantissant fiabilité, performance et maintenance minimale."}$j$::jsonb, 'https://lechantier.ma/en/produits/automatisme-domotique/conductimetre-sup-tds210-b') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('71db0832-9402-5952-b58a-a973b6ca985f'::uuid, '8137d195-6e94-5cbe-81bd-e1a8798098a6'::uuid, 'Contacteur de Puissance LC1D150M', 'Contacteur de puissance Schneider LC1D150M7, contrôle précis moteurs triphasés jusqu''à 75 kW, protection fiable, démarrage sûr et intégration facile✅️', 'Automation & smart home', NULL, NULL, 3800.0, 'MAD', 'Pièce', '1 Pièce', 'https://lechantier.ma/uploads/media/76267925bdf8.webp', $j$["https://lechantier.ma/uploads/media/76267925bdf8.webp", "https://lechantier.ma/uploads/media/6b10be5dc2f0.webp", "https://lechantier.ma/uploads/media/113e9880eb60.webp"]$j$::jsonb, $j$["Témara"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/automatisme-domotique/contacteur-de-puissance-lc1d150m", "category_fr": "Automation & smart home", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Description détaillée et techniqueLe Contacteur de Puissance Schneider Electric LC1D150M7 est un équipement industriel de haute performance conçu pour commander et protéger les moteurs triphasés dans les installations industrielles et tertiaires.\n• ️ Fiable. Robuste. Parfait pour automatisation industrielle et contrôle moteur\n• ️🔹 Type de produit : Contacteur tripolaire de puissance, série TeSys D🔹 Référence : LC1D150M7🔹 Courant nominal (Ie) : 150 A🔹 Puissance moteur (AC-3) : 230 V AC → 40 kW ; 380-400 V AC → 75 kW ; 415-440 V AC → 80 kW🔹 Tension de commande : 220 V AC, 50/60 Hz🔹 Nombre de pôles : 3 (3NO)🔹 Indice de protection : IP20🔹 Type de montage : sur rail DIN🔹 Dimensions (L x H x P) : 150 × 314 × 198 mm🔹 Poids : 4,7 kg🔹 Température de fonctionnement : -25 °C à +60 °C🔹 Température de stockage : -40 °C à +70 °C🔹 Applications typiques : Commande et protection des moteurs triphasés, démarrage et arrêt de pompes, ventilateurs, compresseurs, convoyeurs, gestion de charges importantes dans les armoires électriques🔹 Fonctions principales : Démarrage et arrêt sécurisés des moteurs, protection contre surcharge et court-circuit, intégration facile dans les systèmes d’automatisation existants, conception robuste adaptée aux environnements industriels exigeants🔹 Durabilité et performances : Conçu pour un usage intensif et une longue durée de vie, résistant aux conditions de fonctionnement difficiles🔹 Normes et certifications : Conforme aux standards internationaux pour les équipements industriels🔹 Remarque importante : Modèle prévu pour être discontinué fin 2026. Le modèle de remplacement recommandé est LC1D150AKUE, offrant des fonctionnalités avancées et une compatibilité améliorée avec les systèmes modernes", "technical_specifications_original": "• Description détaillée et techniqueLe Contacteur de Puissance Schneider Electric LC1D150M7 est un équipement industriel de haute performance conçu pour commander et protéger les moteurs triphasés dans les installations industrielles et tertiaires.\n• ️ Fiable. Robuste. Parfait pour automatisation industrielle et contrôle moteur\n• ️🔹 Type de produit : Contacteur tripolaire de puissance, série TeSys D🔹 Référence : LC1D150M7🔹 Courant nominal (Ie) : 150 A🔹 Puissance moteur (AC-3) : 230 V AC → 40 kW ; 380-400 V AC → 75 kW ; 415-440 V AC → 80 kW🔹 Tension de commande : 220 V AC, 50/60 Hz🔹 Nombre de pôles : 3 (3NO)🔹 Indice de protection : IP20🔹 Type de montage : sur rail DIN🔹 Dimensions (L x H x P) : 150 × 314 × 198 mm🔹 Poids : 4,7 kg🔹 Température de fonctionnement : -25 °C à +60 °C🔹 Température de stockage : -40 °C à +70 °C🔹 Applications typiques : Commande et protection des moteurs triphasés, démarrage et arrêt de pompes, ventilateurs, compresseurs, convoyeurs, gestion de charges importantes dans les armoires électriques🔹 Fonctions principales : Démarrage et arrêt sécurisés des moteurs, protection contre surcharge et court-circuit, intégration fa