ficiles🔹 Normes et certifications : Conforme aux standards internationaux pour les équipements industriels🔹 Remarque importante : Modèle prévu pour être discontinué fin 2026. Le modèle de remplacement recommandé est LC1D150AKUE, offrant des fonctionnalités avancées et une compatibilité améliorée avec les systèmes modernes"}$j$::jsonb, 'https://lechantier.ma/en/produits/automatisme-domotique/contacteur-de-puissance-lc1d150m') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
