INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('9c704bab-f4a3-5388-87d3-629ffa332afb'::uuid, '8137d195-6e94-5cbe-81bd-e1a8798098a6'::uuid, 'Démarreur Progressif ATS48D47Q Schneider', 'Démarreur progressif Schneider ATS48D47Q, fiabilité et performance pour moteurs triphasés jusqu''à 45 kW, optimisant démarrage, protection et durée de vie des installations', 'Automation & smart home', NULL, NULL, 6990.0, 'MAD', 'Pièce', '1 Pièce', 'https://lechantier.ma/uploads/media/10095561de90.webp', $j$["https://lechantier.ma/uploads/media/10095561de90.webp"]$j$::jsonb, $j$["Témara"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/automatisme-domotique/demarreur-progressif-ats48d47q-schneider", "category_fr": "Automation & smart home", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Le démarreur progressif Schneider ATS48D47Q (Altistart 48) est conçu pour le démarrage et l’arrêt progressifs des moteurs asynchrones triphasés grâce à son système de contrôle de couple (TCS).\n• ️ Fiable. Robuste. Idéal pour protéger vos installations tout en prolongeant la durée de vie des moteurs\n• ️🔹 Technologie : 6 thyristors avec commande progressive.🔹 Tension d’alimentation : 230–415 V AC.🔹 Courant nominal : 47 A.🔹 Puissance moteur : jusqu’à 45 kW (connexion delta) ou 22 kW (connexion ligne).🔹 Fonctions : démarrage et arrêt progressifs, réduction des contraintes mécaniques/hydrauliques, protection moteur intégrée.🔹 Communication : Modbus intégré via RJ45, extension possible vers Profibus DP, Ethernet, DeviceNet, Fipio.🔹 Certifications : CE, UL, CSA, DNV, GOST, CCC, NOM, SEPRO, TCF.🔹 Applications : pompes, ventilateurs, compresseurs, convoyeurs et machines centrifuges.🔹 Secteurs : construction, industrie alimentaire, chimie.🔹 Dimensions/poids : 160 × 275 × 190 mm / 4,9 kg.", "technical_specifications_original": "• Le démarreur progressif Schneider ATS48D47Q (Altistart 48) est conçu pour le démarrage et l’arrêt progressifs des moteurs asynchrones triphasés grâce à son système de contrôle de couple (TCS).\n• ️ Fiable. Robuste. Idéal pour protéger vos installations tout en prolongeant la durée de vie des moteurs\n• ️🔹 Technologie : 6 thyristors avec commande progressive.🔹 Tension d’alimentation : 230–415 V AC.🔹 Courant nominal : 47 A.🔹 Puissance moteur : jusqu’à 45 kW (connexion delta) ou 22 kW (connexion ligne).🔹 Fonctions : démarrage et arrêt progressifs, réduction des contraintes mécaniques/hydrauliques, protection moteur intégrée.🔹 Communication : Modbus intégré via RJ45, extension possible vers Profibus DP, Ethernet, DeviceNet, Fipio.🔹 Certifications : CE, UL, CSA, DNV, GOST, CCC, NOM, SEPRO, TCF.🔹 Applications : pompes, ventilateurs, compresseurs, convoyeurs et machines centrifuges.🔹 Secteurs : construction, industrie alimentaire, chimie.🔹 Dimensions/poids : 160 × 275 × 190 mm / 4,9 kg.", "specs": "• Le démarreur progressif Schneider ATS48D47Q (Altistart 48) est conçu pour le démarrage et l’arrêt progressifs des moteurs asynchrones triphasés grâce à son système de contrôle de couple (TCS).\n• ️ Fiable. Robuste. Idéal pour protéger vos installations tout en prolongeant la durée de vie des moteurs\n• ️🔹 Technologie : 6 thyristors avec commande progressive.🔹 Tension d’alimentation : 230–415 V AC.🔹 Courant nominal : 47 A.🔹 Puissance moteur : jusqu’à 45 kW (connexion delta) ou 22 kW (connexion ligne).🔹 Fonctions : démarrage et arrêt progressifs, réduction des contraintes mécaniques/hydrauliques, protection moteur intégrée.🔹 Communication : Modbus intégré via RJ45, extension possible vers Profibus DP, Ethernet, DeviceNet, Fipio.🔹 Certifications : CE, UL, CSA, DNV, GOST, CCC, NOM, SEPRO, TCF.🔹 Applications : pompes, ventilateurs, compresseurs, convoyeurs et machines centrifuges.🔹 Secteurs : construction, industrie alimentaire, chimie.🔹 Dimensions/poids : 160 × 275 × 190 mm / 4,9 kg."}$j$::jsonb, 'https://lechantier.ma/en/produits/automatisme-domotique/demarreur-progressif-ats48d47q-schneider') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('c37872a5-534b-5464-ac33-8811f3f8689c'::uuid, '8137d195-6e94-5cbe-81bd-e1a8798098a6'::uuid, 'Horloge Programmable Analogique– 1 Canal', 'Horloge programmable analogique 1 canal, 96 segments, réserve de marche NiMH, pilotée par quartz. Idéale pour automatiser éclairage, chauffage et équipements', 'Automation & smart home', NULL, NULL, 500.0, 'MAD', 'Pièce', '1 Pièce', 'https://lechantier.ma/uploads/media/14647f67c172.webp', $j$["https://lechantier.ma/uploads/media/14647f67c172.webp", "https://lechantier.ma/uploads/media/ee59629cc0b9.webp", "https://lechantier.ma/uploads/media/fb3ae9db2fc9.webp"]$j$::jsonb, $j$["Témara"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/automatisme-domotique/horloge-programmable-analogique-1-canal", "category_fr": "Automation & smart home", "supplier_matching_status": "matched", "technical_specifications_detailed": "• L'horloge SUL 181 d de Theben est une solution fiable et précise pour la gestion automatisée de vos installations électriques. Conçue pour un montage sur rail DIN de 3 modules, elle offre une programmation horaire analogique simple et efficace.🔹 Caractéristiques principales :🔹 Type de programme : Journalier🔹 Nombre de canaux : 1🔹 Segments de commutation : 96 segments pour une flexibilité maximale🔹 Période de commutation minimale : 15 minutes🔹 Précision de marche : ≤ ±1 seconde/jour à 25 °C grâce à son moteur pas à pas piloté par quartz🔹 Correction de l'heure : Ajustable en sens horaire ou anti-horaire, incluant correction simple pour l'heure d'été/hiver🔹 Affichage de l'heure : Aiguilles analogiques avec détection automatique 12h/24h🔹 Réserve de marche : Pile NiMH intégrée assurant environ 36 heures de fonctionnement sans alimentation secteur🔹 Consommation en veille : Environ 0,5 W🔹 Spécifications techniques :🔹 Tension d'alimentation : 110–230 V AC, 50–60 Hz🔹 Puissance de commutation :🔹 16 A à 250 V AC, cos φ = 1🔹 4 A à 250 V AC, cos φ = 0,6🔹 Charge maximale :🔹 1100 W pour lampes à incandescence/halogène🔹 180 W pour lampes LED de 2 à 8 W🔹 180 W pour lampes LED de plus de 8 W🔹 Type de contact : Inverseur🔹 Sortie de commutation : Libre de potentiel et indépendante des phases🔹 Type de raccordement : Bornes à ressort DuoFix pour conducteurs de 0,5 à 2,5 mm²🔹 Commutateur manuel : 3 positions – MARCHE permanente / AUTO / ARRÊT permanent🔹 Indication de l'état de commutation : Visuelle claire🔹 Boîtier : Thermoplastique auto-extinguible résistant aux hautes températures🔹 Indice de protection : IP20🔹 Classe de protection : II selon EN 60730-1🔹 Applications recommandées :🔹 Gestion automatisée de l'éclairage, chauffage, stores, ventilateurs ou tout autre équipement nécessitant une activation/désactivation programmée.🔹 Idéale pour les installations résidentielles, commerciales ou industrielles grâce à sa simplicité et sa fiabilité.", "technical_specifications_original": "• L'horloge SUL 181 d de Theben est une solution fiable et précise pour la gestion automatisée de vos installations électriques. Conçue pour un montage sur rail DIN de 3 modules, elle offre une programmation horaire analogique simple et efficace.🔹 Caractéristiques principales :🔹 Type de programme : Journalier🔹 Nombre de canaux : 1🔹 Segments de commutation : 96 segments pour une flexibilité maximale🔹 Période de commutation minimale : 15 minutes🔹 Précision de marche : ≤ ±1 seconde/jour à 25 °C grâce à son moteur pas à pas piloté par quartz🔹 Correction de l'heure : Ajustable en sens horaire ou anti-horaire, incluant correction simple pour l'heure d'été/hiver🔹 Affichage de l'heure : Aiguilles analogiques avec détection automatique 12h/24h🔹 Réserve de marche : Pile NiMH intégrée assurant environ 36 heures de fonctionnement sans alimentation secteur🔹 Consommation en veille : Environ 0,5 W🔹 Spécifications techniques :🔹 Tension d'alimentation : 110–230 V AC, 50–60 Hz🔹 Puissance de commutation :🔹 16 A à 250 V AC, cos φ = 1🔹 4 A à 250 V AC, cos φ = 0,6🔹 Charge maximale :🔹 1100 W pour lampes à incandescence/halogène🔹 180 W pour lampes LED de 2 à 8 W🔹 180 W pour lampes LED de plus de 8 W🔹 Type de contact : Inverseur🔹 Sortie de commutation : Libre de potentiel et indépendante des phases🔹 Type de raccordement : Bornes à ressort DuoFix pour conducteurs de 0,5 à 2,5 mm²🔹 Commutateur manuel : 3 positions – MARCHE permanente / AUTO / ARRÊT permanent🔹 Indication de l'état de commutation : Visuelle claire🔹 Boîtier : Thermoplastique auto-extinguible résistant aux hautes températures🔹 Indice de protection : IP20🔹 Classe de protection : II selon EN 60730-1🔹 Applications recommandées :🔹 Gestion automatisée de l'éclairage, chauffage, stores, ventilateurs ou tout autre équipement nécessitant une activation/désactivation programmée.🔹 Idéale pour les installations résidentielles, commerciales ou industrielles grâce à sa simplicité et sa fiabilité.", "specs": "• L'horloge SUL 181 d de Theben est une solution fiable et précise pour la gestion automatisée de vos installations électriques. Conçue pour un montage sur rail DIN de 3 modules, elle offre une programmation horaire analogique simple et efficace.🔹 Caractéristiques principales :🔹 Type de programme : Journalier🔹 Nombre de canaux : 1🔹 Segments de commutation : 96 segments pour une flexibilité maximale🔹 Période de commutation minimale : 15 minutes🔹 Précision de marche : ≤ ±1 seconde/jour à 25 °C grâce à son moteur pas à pas piloté par quartz🔹 Correction de l'heure : Ajustable en sens horaire ou anti-horaire, incluant correction simple pour l'heure d'été/hiver🔹 Affichage de l'heure : Aiguilles analogiques avec détection automatique 12h/24h🔹 Réserve de marche : Pile NiMH intégrée assurant environ 36 heures de fonctionnement sans alimentation secteur🔹 Consommation en veille : Environ 0,5 W🔹 Spécifications techniques :🔹 Tension d'alimentation : 110–230 V AC, 50–60 Hz🔹 Puissance de commutation :🔹 16 A à 250 V AC, cos φ = 1🔹 4 A à 250 V AC, cos φ = 0,6🔹 Charge maximale :🔹 1100 W pour lampes à incandescence/halogène🔹 180 W pour lampes LED de 2 à 8 W🔹 180 W pour lampes LED de plus de 8 W🔹 Type de contact : Inverseur🔹 Sortie de commutation : Libre de potentiel et indépendante des phases🔹 Type de raccordement : Bornes à ressort DuoFix pour conducteurs de 0,5 à 2,5 mm²🔹 Commutateur manuel : 3 positions – MARCHE permanente / AUTO / ARRÊT permanent🔹 Indication de l'état de commutation : Visuelle claire🔹 Boîtier : Thermoplastique auto-extinguible résistant aux hautes températures🔹 Indice de protection : IP20🔹 Classe de protection : II selon EN 60730-1🔹 Applications recommandées :🔹 Gestion automatisée de l'éclairage, chauffage, stores, ventilateurs ou tout autre équipement nécessitant une activation/désactivation programmée.🔹 Idéale pour les installations résidentielles, commerciales ou industrielles grâce à sa simplicité et sa fiabilité."}$j$::jsonb, 'https://lechantier.ma/en/produits/automatisme-domotique/horloge-programmable-analogique-1-canal') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('fdd3962b-9d0e-5226-81b2-6fb2a9b80bad'::uuid, '8137d195-6e94-5cbe-81bd-e1a8798098a6'::uuid, 'Variateur de Vitesse ATV630D30N4', 'Variateur de vitesse Schneider ATV630D30N4, contrôle précis des moteurs triphasés jusqu''à 30 kW, fiable, performant et idéal pour l''automatisation industrielle', 'Automation & smart home', NULL, NULL, 24570.0, 'MAD', 'Pièce', '1 Pièce', 'https://lechantier.ma/uploads/media/b10a7b959e32.webp', $j$["https://lechantier.ma/uploads/media/b10a7b959e32.webp", "https://lechantier.ma/uploads/media/58f00f5d555a.webp", "https://lechantier.ma/uploads/media/8d4bb81fbef6.webp", "https://lechantier.ma/uploads/media/933b5f173196.webp"]$j$::jsonb, $j$["Témara"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/automatisme-domotique/variateur-de-vitesse-atv630d30n4", "category_fr": "Automation & smart home", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Le Variateur de Vitesse Schneider Altivar Process ATV600 est conçu pour le contrôle efficace des moteurs synchrones et asynchrones triphasés, avec un accent sur la flexibilité et l’économie d’énergie.\n• ️ Fiable. Robuste. Idéal pour les applications industrielles et les services publics, avec réduction de la consommation et optimisation des performances\n• ️🔹 Technologie : Variateur de fréquence pour moteurs asynchrones et synchrones.🔹 Puissance moteur : jusqu’à 30 kW / 40 HP (légère surcharge 120 %) ou 22 kW / 30 HP (surcharge importante 150 %).🔹 Tension d’alimentation : 380–480 V AC.🔹 Communication intégrée : 3 ports RJ45, 1 port Ethernet, 2 ports série.🔹 Fonctions énergie : mode « Stop and Go » pour économiser jusqu’à 30 % d’énergie en veille.🔹 Applications : eau et eaux usées, exploitation minière, minéraux et métaux, pétrole et gaz, agroalimentaire.🔹 Accessoires et options : ventilateur, terminal graphique, modules E/S, modules de communication, filtres CEM.🔹 Montage : vertical, +/-10° sur panneau ou mur.🔹 Dimensions / Poids : 226 × 673 × 271 mm / 28 kg.🔹 Avantages : gestion de l’énergie, performance des processus, réduction du coût total de possession, intégration facile dans les systèmes industriels.", "technical_specifications_original": "• Le Variateur de Vitesse Schneider Altivar Process ATV600 est conçu pour le contrôle efficace des moteurs synchrones et asynchrones triphasés, avec un accent sur la flexibilité et l’économie d’énergie.\n• ️ Fiable. Robuste. Idéal pour les applications industrielles et les services publics, avec réduction de la consommation et optimisation des performances\n• ️🔹 Technologie : Variateur de fréquence pour moteurs asynchrones et synchrones.🔹 Puissance moteur : jusqu’à 30 kW / 40 HP (légère surcharge 120 %) ou 22 kW / 30 HP (surcharge importante 150 %).🔹 Tension d’alimentation : 380–480 V AC.🔹 Communication intégrée : 3 ports RJ45, 1 port Ethernet, 2 ports série.🔹 Fonctions énergie : mode « Stop and Go » pour économiser jusqu’à 30 % d’énergie en veille.🔹 Applications : eau et eaux usées, exploitation minière, minéraux et métaux, pétrole et gaz, agroalimentaire.🔹 Accessoires et options : ventilateur, terminal graphique, modules E/S, modules de communication, filtres CEM.🔹 Montage : vertical, +/-10° sur panneau ou mur.🔹 Dimensions / Poids : 226 × 673 × 271 mm / 28 kg.🔹 Avantages : gestion de l’énergie, performance des processus, réduction du coût total de possession, intégration facile dans les systèmes industriels.", "specs": "• Le Variateur de Vitesse Schneider Altivar Process ATV600 est conçu pour le contrôle efficace des moteurs synchrones et asynchrones triphasés, avec un accent sur la flexibilité et l’économie d’énergie.\n• ️ Fiable. Robuste. Idéal pour les applications industrielles et les services publics, avec réduction de la consommation et optimisation des performances\n• ️🔹 Technologie : Variateur de fréquence pour moteurs asynchrones et synchrones.🔹 Puissance moteur : jusqu’à 30 kW / 40 HP (légère surcharge 120 %) ou 22 kW / 30 HP (surcharge importante 150 %).🔹 Tension d’alimentation : 380–480 V AC.🔹 Communication intégrée : 3 ports RJ45, 1 port Ethernet, 2 ports série.🔹 Fonctions énergie : mode « Stop and Go » pour économiser jusqu’à 30 % d’énergie en veille.🔹 Applications : eau et eaux usées, exploitation minière, minéraux et métaux, pétrole et gaz, agroalimentaire.🔹 Accessoires et options : ventilateur, terminal graphique, modules E/S, modules de communication, filtres CEM.🔹 Montage : vertical, +/-10° sur panneau ou mur.🔹 Dimensions / Poids : 226 × 673 × 271 mm / 28 kg.🔹 Avantages : gestion de l’énergie, performance des processus, réduction du coût total de possession, intégration facile dans les systèmes industriels."}$j$::jsonb, 'https://lechantier.ma/en/produits/automatisme-domotique/variateur-de-vitesse-atv630d30n4') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
