INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('e1b4e36b-be65-56ec-af02-8091b4181ca7'::uuid, '9905df39-f4ef-5a6f-ab9d-9ff7371412a6'::uuid, 'BARRIERE METALLIQUE', 'Barrières métalliques – Afrique Découpe Laser', 'Security bars', NULL, NULL, 600.0, 'MAD', 'Pièce', '50 Pièce', 'https://lechantier.ma/uploads/media/670a08914222.webp', $j$["https://lechantier.ma/uploads/media/670a08914222.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/barreaux/barriere-metallique", "category_fr": "Security bars", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Les barrières métalliques d’Afrique Découpe Laser sont conçues pour allier sécurité, robustesse et design moderne. Fabriquées à partir d’acier de haute qualité, elles bénéficient d’une découpe laser de précision assurant des finitions impeccables et une grande durabilité face aux conditions climatiques les plus exigeantes.Disponibles dans plusieurs modèles (barrières de sécurité, barrières décoratives, barrières urbaines et industrielles), elles répondent aux besoins des secteurs résidentiel, commercial et industriel.Chaque barrière peut être personnalisée en dimensions, motifs et revêtements grâce à notre expertise en découpe laser, pliage et peinture époxy, garantissant une protection optimale contre la corrosion.Caractéristiques principales :Structure métallique robuste et durableDécoupe laser haute précision pour un rendu esthétique supérieurFinition peinture époxy anticorrosionFabrication sur mesure (dimensions, motifs et couleurs)Conformes aux normes de sécurité et d’urbanismeApplications : sécurisation des espaces publics et privés, délimitation de zones industrielles, parkings, jardins, sites commerciaux et résidences.", "technical_specifications_original": "• Les barrières métalliques d’Afrique Découpe Laser sont conçues pour allier sécurité, robustesse et design moderne. Fabriquées à partir d’acier de haute qualité, elles bénéficient d’une découpe laser de précision assurant des finitions impeccables et une grande durabilité face aux conditions climatiques les plus exigeantes.Disponibles dans plusieurs modèles (barrières de sécurité, barrières décoratives, barrières urbaines et industrielles), elles répondent aux besoins des secteurs résidentiel, commercial et industriel.Chaque barrière peut être personnalisée en dimensions, motifs et revêtements grâce à notre expertise en découpe laser, pliage et peinture époxy, garantissant une protection optimale contre la corrosion.Caractéristiques principales :Structure métallique robuste et durableDécoupe laser haute précision pour un rendu esthétique supérieurFinition peinture époxy anticorrosionFabrication sur mesure (dimensions, motifs et couleurs)Conformes aux normes de sécurité et d’urbanismeApplications : sécurisation des espaces publics et privés, délimitation de zones industrielles, parkings, jardins, sites commerciaux et résidences.", "specs": "• Les barrières métalliques d’Afrique Découpe Laser sont conçues pour allier sécurité, robustesse et design moderne. Fabriquées à partir d’acier de haute qualité, elles bénéficient d’une découpe laser de précision assurant des finitions impeccables et une grande durabilité face aux conditions climatiques les plus exigeantes.Disponibles dans plusieurs modèles (barrières de sécurité, barrières décoratives, barrières urbaines et industrielles), elles répondent aux besoins des secteurs résidentiel, commercial et industriel.Chaque barrière peut être personnalisée en dimensions, motifs et revêtements grâce à notre expertise en découpe laser, pliage et peinture époxy, garantissant une protection optimale contre la corrosion.Caractéristiques principales :Structure métallique robuste et durableDécoupe laser haute précision pour un rendu esthétique supérieurFinition peinture époxy anticorrosionFabrication sur mesure (dimensions, motifs et couleurs)Conformes aux normes de sécurité et d’urbanismeApplications : sécurisation des espaces publics et privés, délimitation de zones industrielles, parkings, jardins, sites commerciaux et résidences."}$j$::jsonb, 'https://lechantier.ma/en/produits/barreaux/barriere-metallique') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
