INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('9004ef87-9969-50d6-9440-ac05db0eb7b4'::uuid, 'ab2f4b77-280a-5513-9f2c-f8a5ff1a1937'::uuid, 'CIMENT 45 LAFARGE HOLCIM', 'Le CPJ 45 est un ciment Portland composé (type CEM II/A ou B-L 42,5) produit par Lafarge Maroc, conforme à la norme NM 10.1.004', 'Ready-mix concrete', NULL, NULL, 1600.0, 'MAD', 'm²', '500 Kilogramme', 'https://lechantier.ma/uploads/media/f2fc7999f1a2.webp', $j$["https://lechantier.ma/uploads/media/f2fc7999f1a2.webp"]$j$::jsonb, $j$["Agadir"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/beton-pret-a-l-emploi/ciment-45-lafarge-holcim", "category_fr": "Matériaux de construction", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Type : CEM II/A-L ou B-L 42,5 (CPJ 45)Classe de résistance : ≥ 42,5 MPa à 28 joursConstituants : Clinker, calcaire finement moulu, gypseTemps de prise : normal à rapideExcellente ouvrabilité et maniabilitéRéduction de l’empreinte carbone par rapport au CEM I", "technical_specifications_original": "• Type : CEM II/A-L ou B-L 42,5 (CPJ 45)Classe de résistance : ≥ 42,5 MPa à 28 joursConstituants : Clinker, calcaire finement moulu, gypseTemps de prise : normal à rapideExcellente ouvrabilité et maniabilitéRéduction de l’empreinte carbone par rapport au CEM I", "specs": "• Type : CEM II/A-L ou B-L 42,5 (CPJ 45)Classe de résistance : ≥ 42,5 MPa à 28 joursConstituants : Clinker, calcaire finement moulu, gypseTemps de prise : normal à rapideExcellente ouvrabilité et maniabilitéRéduction de l’empreinte carbone par rapport au CEM I"}$j$::jsonb, 'https://lechantier.ma/en/produits/beton-pret-a-l-emploi/ciment-45-lafarge-holcim') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUD