INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('6db45115-3a93-55db-842a-9e9c028cdfd4'::uuid, '80a799fe-cb3e-5be3-9e1c-b071de8fbf17'::uuid, 'Armoires électrique métalliques', 'Nous proposons une gamme variée d''armoires électriques métalliques et coffrets électrique métalliques et en PVC.', 'Boxes & enclosures', NULL, NULL, 1000.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/50ff24295553.webp', $j$["https://lechantier.ma/uploads/media/50ff24295553.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/boite-et-coffret/armoires-electrique-metalliques", "category_fr": "Boxes & enclosures", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Armoires électriques métalliques : Robustes et variées en tailles, nos armoires électriques métalliques assurent la sécurité et la protection de vos équipements électriques dans divers environnements industriels.Coffrets électriques métalliques : Nos coffrets métalliques offrent une installation sûre et pratique pour vos composants électriques, avec une gamme de tailles et de configurations pour répondre à vos besoins spécifiques en matière de protection et de distribution électrique.Coffrets électriques en PVC : Légers, résistants à l'humidité et abordables, nos coffrets en PVC fournissent une solution économique pour protéger vos équipements électriques, tant à l'intérieur qu'à l'extérieur, tout en offrant une installation facile et une longue durée de vie.", "technical_specifications_original": "• Armoires électriques métalliques : Robustes et variées en tailles, nos armoires électriques métalliques assurent la sécurité et la protection de vos équipements électriques dans divers environnements industriels.Coffrets électriques métalliques : Nos coffrets métalliques offrent une installation sûre et pratique pour vos composants électriques, avec une gamme de tailles et de configurations pour répondre à vos besoins spécifiques en matière de protection et de distribution électrique.Coffrets électriques en PVC : Légers, résistants à l'humidité et abordables, nos coffrets en PVC fournissent une solution économique pour protéger vos équipements électriques, tant à l'intérieur qu'à l'extérieur, tout en offrant une installation facile et une longue durée de vie.", "specs": "• Armoires électriques métalliques : Robustes et variées en tailles, nos armoires électriques métalliques assurent la sécurité et la protection de vos équipements électriques dans divers environnements industriels.Coffrets électriques métalliques : Nos coffrets métalliques offrent une installation sûre et pratique pour vos composants électriques, avec une gamme de tailles et de configurations pour répondre à vos besoins spécifiques en matière de protection et de distribution électrique.Coffrets électriques en PVC : Légers, résistants à l'humidité et abordables, nos coffrets en PVC fournissent une solution économique pour protéger vos équipements électriques, tant à l'intérieur qu'à l'extérieur, tout en offrant une installation facile et une longue durée de vie."}$j$::jsonb, 'https://lechantier.ma/en/produits/boite-et-coffret/armoires-electrique-metalliques') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('6a995377-a646-5883-8cc1-841ce032d87a'::uuid, '8137d195-6e94-5cbe-81bd-e1a8798098a6'::uuid, 'Coffret Metalbox 300x250 à 1200x800', 'Coffrets Metalbox robustes de 300x250x150 à 1200x800x320 mm, fiables et faciles à installer, pour protéger et organiser vos équipements électriques.', 'Boxes & enclosures', NULL, NULL, 600.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/278d40307a03.webp', $j$["https://lechantier.ma/uploads/media/278d40307a03.webp", "https://lechantier.ma/uploads/media/e2523b5b8742.webp"]$j$::jsonb, $j$["Témara"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/boite-et-coffret/coffret-metalbox-300x250-a-1200x800", "category_fr": "Boxes & enclosures", "supplier_matching_status": "matched", "technical_specifications_detailed": "• 🔹 Coffrets métalliques Metalbox – Protection et distribution électrique fiableFiable. Robuste. Conçu pour sécuriser et organiser tous vos équipements électriques, des installations domestiques aux projets industriels\n• ️Caractéristiques techniques :Dimensions disponibles : 300×250×150 mm → 1200×800×320 mm, adaptées à tous types de besoins.Matériau : Tôle d’acier de haute qualité, épaisseur 1,2 à 1,5 mm selon taille.Protection : IP55 ou IP66 selon modèle, résistant à la poussière, projections d’eau et chocs mécaniques.Montage : Fixation murale ou sur pied, avec trappe pour passage de câbles.Compatibilité : Pour appareillage électrique standard (disjoncteurs, borniers, relais, contacteurs).Sécurité : Verrouillage possible, résistance aux manipulations et à la corrosion.Finition : Peinture époxy anticorrosion, couleur grise standard ou personnalisable.Accessoires : Possibilité d’ajouter panneaux DIN, support interne pour câblage et séparateurs modulables.Applications :Distribution électrique dans bâtiments résidentiels, commerciaux et industriels.Protection des circuits CFO, éclairage et alimentation électrique.Convient pour installations temporaires ou permanentes.", "technical_specifications_original": "• 🔹 Coffrets métalliques Metalbox – Protection et distribution électrique fiableFiable. Robuste. Conçu pour sécuriser et organiser tous vos équipements électriques, des installations domestiques aux projets industriels\n• ️Caractéristiques techniques :Dimensions disponibles : 300×250×150 mm → 1200×800×320 mm, adaptées à tous types de besoins.Matériau : Tôle d’acier de haute qualité, épaisseur 1,2 à 1,5 mm selon taille.Protection : IP55 ou IP66 selon modèle, résistant à la poussière, projections d’eau et chocs mécaniques.Montage : Fixation murale ou sur pied, avec trappe pour passage de câbles.Compatibilité : Pour appareillage électrique standard (disjoncteurs, borniers, relais, contacteurs).Sécurité : Verrouillage possible, résistance aux manipulations et à la corrosion.Finition : Peinture époxy anticorrosion, couleur grise standard ou personnalisable.Accessoires : Possibilité d’ajouter panneaux DIN, support interne pour câblage et séparateurs modulables.Applications :Distribution électrique dans bâtiments résidentiels, commerciaux et industriels.Protection des circuits CFO, éclairage et alimentation électrique.Convient pour installations temporaires ou permanentes.", "specs": "• 🔹 Coffrets métalliques Metalbox – Protection et distribution électrique fiableFiable. Robuste. Conçu pour sécuriser et organiser tous vos équipements électriques, des installations domestiques aux projets industriels\n• ️Caractéristiques techniques :Dimensions disponibles : 300×250×150 mm → 1200×800×320 mm, adaptées à tous types de besoins.Matériau : Tôle d’acier de haute qualité, épaisseur 1,2 à 1,5 mm selon taille.Protection : IP55 ou IP66 selon modèle, résistant à la poussière, projections d’eau et chocs mécaniques.Montage : Fixation murale ou sur pied, avec trappe pour passage de câbles.Compatibilité : Pour appareillage électrique standard (disjoncteurs, borniers, relais, contacteurs).Sécurité : Verrouillage possible, résistance aux manipulations et à la corrosion.Finition : Peinture époxy anticorrosion, couleur grise standard ou personnalisable.Accessoires : Possibilité d’ajouter panneaux DIN, support interne pour câblage et séparateurs modulables.Applications :Distribution électrique dans bâtiments résidentiels, commerciaux et industriels.Protection des circuits CFO, éclairage et alimentation électrique.Convient pour installations temporaires ou permanentes."}$j$::jsonb, 'https://lechantier.ma/en/produits/boite-et-coffret/coffret-metalbox-300x250-a-1200x800') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('37a691eb-f63d-560b-bb81-2e287f2b6099'::uuid, '8137d195-6e94-5cbe-81bd-e1a8798098a6'::uuid, 'Coffret Metalbox 800x550x161', 'Coffret métallique Hager 800x550x161 120M FWB52S Marque : HAGER Référence : FWB52S Gamme : METALBOX Type : Métallique Dimensions (HxLxP) : 800x550x161', 'Boxes & enclosures', NULL, NULL, 2000.0, 'MAD', 'Pièce', '1 Pièce', 'https://lechantier.ma/uploads/media/1ff262e247a4.webp', $j$["https://lechantier.ma/uploads/media/1ff262e247a4.webp"]$j$::jsonb, $j$["Témara"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/boite-et-coffret/coffret-metalbox-800x550x161", "category_fr": "Boxes & enclosures", "supplier_matching_status": "matched", "technical_specifications_detailed": "• 🔹 Les coffrets métalliques Metalbox HAGER assurent la réception et la protection de l’appareillage électrique. 🔹 Disponible dans plusieurs dimensions, jusqu’à 1200×800×320 mm, adaptés à tous types d’installations. 🔹 Tôle acier 1,2 à 1,5 mm, cuve pliée et soudée avec trappe pour passage de câbles. 🔹 Porte simple volet réversible, renforcée pour les hauteurs supérieures à 700 mm, fermeture quart de tour avec serrure DIN 3 mm acier. 🔹 Peinture époxy polyester en poudre structurée RAL 7035, assurant durabilité et résistance. 🔹 Fond avec trous de fixation et bossages pour aération, pour une installation facile et sécurisée. 🔹 Degré de protection IP55 selon EN 60529, garantissant étanchéité et sécurité en environnement industriel.", "technical_specifications_original": "• 🔹 Les coffrets métalliques Metalbox HAGER assurent la réception et la protection de l’appareillage électrique. 🔹 Disponible dans plusieurs dimensions, jusqu’à 1200×800×320 mm, adaptés à tous types d’installations. 🔹 Tôle acier 1,2 à 1,5 mm, cuve pliée et soudée avec trappe pour passage de câbles. 🔹 Porte simple volet réversible, renforcée pour les hauteurs supérieures à 700 mm, fermeture quart de tour avec serrure DIN 3 mm acier. 🔹 Peinture époxy polyester en poudre structurée RAL 7035, assurant durabilité et résistance. 🔹 Fond avec trous de fixation et bossages pour aération, pour une installation facile et sécurisée. 🔹 Degré de protection IP55 selon EN 60529, garantissant étanchéité et sécurité en environnement industriel.", "specs": "• 🔹 Les coffrets métalliques Metalbox HAGER assurent la réception et la protection de l’appareillage électrique. 🔹 Disponible dans plusieurs dimensions, jusqu’à 1200×800×320 mm, adaptés à tous types d’installations. 🔹 Tôle acier 1,2 à 1,5 mm, cuve pliée et soudée avec trappe pour passage de câbles. 🔹 Porte simple volet réversible, renforcée pour les hauteurs supérieures à 700 mm, fermeture quart de tour avec serrure DIN 3 mm acier. 🔹 Peinture époxy polyester en poudre structurée RAL 7035, assurant durabilité et résistance. 🔹 Fond avec trous de fixation et bossages pour aération, pour une installation facile et sécurisée. 🔹 Degré de protection IP55 selon EN 60529, garantissant étanchéité et sécurité en environnement industriel."}$j$::jsonb, 'https://lechantier.ma/en/produits/boite-et-coffret/coffret-metalbox-800x550x161') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('42197f37-ab14-5ecb-9e83-e957010f59ae'::uuid, 'e4105a41-8939-54d0-afd2-23900a8f418d'::uuid, 'connector wago', 'Splicing connector with levers; for all conductor types; max. 4 mm²; 5-conductor; gray housing; Surrounding air temperature: max 40°C; 2,50 mm²; gray', 'Wiring connections', NULL, NULL, 7.0, 'MAD', 'Pièce', '40 Pièce', 'https://lechantier.ma/uploads/media/444b1c1c932d.webp', $j$["https://lechantier.ma/uploads/media/444b1c1c932d.webp", "https://lechantier.ma/uploads/media/acfdf69f54e3.webp", "https://lechantier.ma/uploads/media/6e00a83924a1.webp"]$j$::jsonb, $j$["Casablanca"]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/branchement/connector-wago", "category_fr": "Wiring connections", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Our splicing connector with levers (item number 222-415) simplifies electrical installations. From wiring intercom systems to installing electrical ovens, connecting different conductor types is quick and simple with WAGO's compact 222 Series splicing connector, which allows you to quickly and safely connect different types of conductors. Ensure that the strip lengths are between 9 and 10 mm when connecting conductors to splicing connector with levers. This splicing connector has a rated voltage of 400 V and can handle currents up to 32 A, making it ideal for high-load applications. This product features conductor terminals and utilizes CAGE CLAMP®. Our reliable and maintenance-free CAGE CLAMP® connection makes it easy to connect all conductor types without having to prepare the conductor. For example, you don't need to crimp ferrules. The item's dimensions are (26.6 x 14.5 x 20.5) mm (width x height x depth). Splicing connector with levers is suitable for conductor cross sections ranging from 0.08 mm² to 2.5 mm².", "technical_specifications_original": "• Our splicing connector with levers (item number 222-415) simplifies electrical installations. From wiring intercom systems to installing electrical ovens, connecting different conductor types is quick and simple with WAGO's compact 222 Series splicing connector, which allows you to quickly and safely connect different types of conductors. Ensure that the strip lengths are between 9 and 10 mm when connecting conductors to splicing connector with levers. This splicing connector has a rated voltage of 400 V and can handle currents up to 32 A, making it ideal for high-load applications. This product features conductor terminals and utilizes CAGE CLAMP®. Our reliable and maintenance-free CAGE CLAMP® connection makes it easy to connect all conductor types without having to prepare the conductor. For example, you don't need to crimp ferrules. The item's dimensions are (26.6 x 14.5 x 20.5) mm (width x height x depth). Splicing connector with levers is suitable for conductor cross sections ranging from 0.08 mm² to 2.5 mm².", "specs": "• Our splicing connector with levers (item number 222-415) simplifies electrical installations. From wiring intercom systems to installing electrical ovens, connecting different conductor types is quick and simple with WAGO's compact 222 Series splicing connector, which allows you to quickly and safely connect different types of conductors. Ensure that the strip lengths are between 9 and 10 mm when connecting conductors to splicing connector with levers. This splicing connector has a rated voltage of 400 V and can handle currents up to 32 A, making it ideal for high-load applications. This product features conductor terminals and utilizes CAGE CLAMP®. Our reliable and maintenance-free CAGE CLAMP® connection makes it easy to connect all conductor types without having to prepare the conductor. For example, you don't need to crimp ferrules. The item's dimensions are (26.6 x 14.5 x 20.5) mm (width x height x depth). Splicing connector with levers is suitable for conductor cross sections ranging from 0.08 mm² to 2.5 mm²."}$j$::jsonb, 'https://lechantier.ma/en/produits/branchement/connector-wago') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
