INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('b0f8a90a-14d3-5302-b6d6-31ed98b8ab54'::uuid, '80a799fe-cb3e-5be3-9e1c-b071de8fbf17'::uuid, 'Contacteurs électrique Schneider', 'Contacteurs électrique Schneider.', 'Wiring connections', NULL, NULL, 180.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/79c9bd145879.webp', $j$["https://lechantier.ma/uploads/media/79c9bd145879.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/branchement/contacteurs-electrique-schneider", "category_fr": "Wiring connections", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Découvrez notre gamme complète de contacteurs électriques de la marque schneider, offrant une solution de commutation fiable pour une puissance allant de 3 kW à 400 kW. Disponibles dans une variété de tensions, y compris alternatif et continu (12V, 24V, 48V, 220V, 400V), ces contacteurs sont conçus pour répondre à vos besoins spécifiques en matière de commande de moteurs et de charges électriques, offrant une performance optimale et une durabilité exceptionnelle dans diverses applications industrielles et commerciales. Fabriqués selon les normes les plus strictes de qualité et de sécurité, les contacteurs Schneider assurent une commutation efficace et sans faille pour une exploitation en toute confiance de vos équipements électriques.", "technical_specifications_original": "• Découvrez notre gamme complète de contacteurs électriques de la marque schneider, offrant une solution de commutation fiable pour une puissance allant de 3 kW à 400 kW. Disponibles dans une variété de tensions, y compris alternatif et continu (12V, 24V, 48V, 220V, 400V), ces contacteurs sont conçus pour répondre à vos besoins spécifiques en matière de commande de moteurs et de charges électriques, offrant une performance optimale et une durabilité exceptionnelle dans diverses applications industrielles et commerciales. Fabriqués selon les normes les plus strictes de qualité et de sécurité, les contacteurs Schneider assurent une commutation efficace et sans faille pour une exploitation en toute confiance de vos équipements électriques.", "specs": "• Découvrez notre gamme complète de contacteurs électriques de la marque schneider, offrant une solution de commutation fiable pour une puissance allant de 3 kW à 400 kW. Disponibles dans une variété de tensions, y compris alternatif et continu (12V, 24V, 48V, 220V, 400V), ces contacteurs sont conçus pour répondre à vos besoins spécifiques en matière de commande de moteurs et de charges électriques, offrant une performance optimale et une durabilité exceptionnelle dans diverses applications industrielles et commerciales. Fabriqués selon les normes les plus strictes de qualité et de sécurité, les contacteurs Schneider assurent une commutation efficace et sans faille pour une exploitation en toute confiance de vos équipements électriques."}$j$::jsonb, 'https://lechantier.ma/en/produits/branchement/contacteurs-electrique-schneider') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
INSERT INTO public.products (id, user_id, title, description, category, brand, sku, price, currency, unit, min_quantity, cover, gallery, delivery_cities, attributes, source_url) VALUES ('163fd5eb-ded6-5448-853e-b85bc0bc0482'::uuid, '80a799fe-cb3e-5be3-9e1c-b071de8fbf17'::uuid, 'Démarreur progressif Altistart', 'Découvrez notre gamme de démarreurs progressifs de la marque Schneider, offrant une solution de démarrage en douceur.', 'Wiring connections', NULL, NULL, 2500.0, 'MAD', 'm²', '1 Pièce', 'https://lechantier.ma/uploads/media/486631d5ae9f.webp', $j$["https://lechantier.ma/uploads/media/486631d5ae9f.webp"]$j$::jsonb, $j$[]$j$::jsonb, $j${"source": "lechantier", "source_url": "https://lechantier.ma/en/produits/branchement/demarreur-progressif-altistart", "category_fr": "Wiring connections", "supplier_matching_status": "matched", "technical_specifications_detailed": "• Une large gamme de puissances, allant de 0,75 kW à 400 kW. Ces démarreurs progressifs permettent de réduire les pics de courant et d'assurer un démarrage en toute sécurité pour les moteurs électriques de différentes tailles. Grâce à leur conception robuste et à leurs fonctionnalités avancées, ils garantissent une performance fiable et une protection optimale pour vos équipements, contribuant ainsi à prolonger leur durée de vie et à réduire les coûts de maintenance. Choisissez Schneider pour une solution de démarrage progressif efficace et éprouvée.", "technical_specifications_original": "• Une large gamme de puissances, allant de 0,75 kW à 400 kW. Ces démarreurs progressifs permettent de réduire les pics de courant et d'assurer un démarrage en toute sécurité pour les moteurs électriques de différentes tailles. Grâce à leur conception robuste et à leurs fonctionnalités avancées, ils garantissent une performance fiable et une protection optimale pour vos équipements, contribuant ainsi à prolonger leur durée de vie et à réduire les coûts de maintenance. Choisissez Schneider pour une solution de démarrage progressif efficace et éprouvée.", "specs": "• Une large gamme de puissances, allant de 0,75 kW à 400 kW. Ces démarreurs progressifs permettent de réduire les pics de courant et d'assurer un démarrage en toute sécurité pour les moteurs électriques de différentes tailles. Grâce à leur conception robuste et à leurs fonctionnalités avancées, ils garantissent une performance fiable et une protection optimale pour vos équipements, contribuant ainsi à prolonger leur durée de vie et à réduire les coûts de maintenance. Choisissez Schneider pour une solution de démarrage progressif efficace et éprouvée."}$j$::jsonb, 'https://lechantier.ma/en/produits/branchement/demarreur-progressif-altistart') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, category = EXCLUDED.category, brand = EXCLUDED.brand, sku = EXCLUDED.sku, price = EXCLUDED.price, currency = EXCLUDED.currency, unit = EXCLUDED.unit, min_quantity = EXCLUDED.min_quantity, cover = EXCLUDED.cover, gallery = EXCLUDED.gallery, delivery_cities = EXCLUDED.delivery_cities, attributes = EXCLUDED.attributes, source_url = EXCLUDED.source_url, user_id = EXCLUDED.user_id, updated_at = NOW();
